import java.io.*;import java.util.Scanner;
public class FileStatistics { public static void main(String[] a){Scanner s=new Scanner(System.in);System.out.print("File path: ");String path=s.nextLine();int chars=0,lines=0,words=0;try(BufferedReader r=new BufferedReader(new FileReader(path))){String line;while((line=r.readLine())!=null){lines++;chars+=line.length();String t=line.trim();if(!t.isEmpty())words+=t.split("\\s+").length;}System.out.println("Characters: "+chars+" Lines: "+lines+" Words: "+words);}catch(IOException e){System.out.println("File error: "+e.getMessage());}s.close();} }
